pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A "dead" gap is one too small for typical items (assume min useful size ~10,
    // but with unknown distribution, treat gaps below ~20 as risky).
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            // The smaller (and thus less reusable) the gap, the worse.
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Perfect fit: zero dead space, big reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward tight fits relative to bin residual (high fill ratio of the used space).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if the post residual can host the next item, this is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            // Gap exists but next item won't fit: mild penalty for stranding space.
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when avoidable.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin unless current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if mean residual across open bins is already small (they're full-ish),
        // a new bin is reasonable: soften the penalty.
        score -= mean_residual * 0.6;
    }

    // Mild progression coupling: early in the stream, be slightly more willing
    // to open bins (flexibility later); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    } else {
        score -= progress * 8.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's already nearly full — using it is good (consolidation).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (near-zero post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits too: mild reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // Next item would NOT fit here: penalize leaving residual that
            // cannot accommodate the lookahead item (dead-space risk).
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(50.0) * 2.0;
        }
    }

    // Compare post_residual relative to the mean residual of open bins:
    // placing into a bin that ends far below the mean wastes capacity elsewhere.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        let dev = (post_residual as f64 - mean_post).abs();
        score += 0.5 * dev;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Exception: a new bin is fine if the item is huge and next item is large
        // (pairing large items together in fresh bins).
        if item_size >= bin_capacity / 2 && next_item_size >= bin_capacity / 2 {
            score -= 120.0;
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Refined fit tiers: stronger near-perfect rewards
    if post_residual == 0 {
        score -= 1350.0;
    } else if post_residual <= 3 {
        score -= 340.0;
    } else if post_residual <= 10 {
        score -= 95.0;
    } else if post_residual <= 22 {
        score -= 28.0;
    } else if post_residual <= 38 {
        score -= 9.0;
    }

    // 2-step lookahead with dead-space-ratio shaping
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 170.0 - fill_after_next * 0.8;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 55.0;
            }
            if fill_after_next == 0.0 {
                score -= 40.0;
            }
            let dsr = fill_after_next / bin_capacity as f64;
            if dsr > 0.18 {
                score += 26.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 28.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= mean_residual * 0.6 {
                score -= 9.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 48.0 + gap * 0.42;
            if gap > 42.0 {
                score += 22.0;
            }
            if gap > 0.6 * next_item_size as f64 {
                score += 16.0;
            }
            if gap <= item_size as f64 {
                score -= 10.0;
            }
        }
    }

    // Above-average residual bins are good targets
    score -= 0.45 * (bin_residual as f64 - mean_residual);

    // Last chance: favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Small unusable dead space penalty
    if post_residual > 0 && post_residual < 10 && next_item_size as f64 > post_residual as f64 {
        score += 30.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score += 62.0;
        let cap_half = bin_capacity / 2;
        if item_size >= cap_half {
            score -= 90.0;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size >= cap_half && next_item_size > post_residual {
            score -= 30.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 42.0 * (1.0 - progress);
        score += 0.18 * open_bins_count as f64;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 65.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= bin_capacity / 4 {
            score += 25.0;
        }
    }

    // Mild consolidation pressure
    score -= 0.1 * open_bins_count as f64;

    // Residual that can chain-fit the next item twice is valuable
    if next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        if after >= next_item_size && after <= bin_capacity / 4 {
            score -= 48.0;
        }
        if after == 0 {
            score -= 110.0;
        }
    }

    // Late-stream fine tuning
    if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }
    if total_items > 0 && step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 20.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 28.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Slight preference for leaving room >= next item
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: bins with residual above average are good targets
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize early opening
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post-residual, with non-linear polynomial shaping.
    let x = post / cap; // normalized post residual in [0, 1]
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (reward small post_residual);
    // later, keep residual flexibility (penalize tiny residuals less).
    let poly = 1.0 + 3.0 * progress - 4.0 * progress * progress;
    score += poly * (x * x * cap);

    // Dead-space penalty: non-linearly penalize residuals that cannot fit
    // the next item (smooth via ratio, not a hard threshold).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 20.0 * gap * gap * cap;
    } else if next_item_size > 0 {
        // Reward leaving exactly usable space for the next item.
        let usable = 1.0 - ((next_item_size as f64 - post).abs() / cap);
        score -= 5.0 * usable * usable;
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (consolidation pressure),
    // coupled smoothly with mean residual divergence.
    let diverge = (mean_residual - post).abs() / cap;
    score += 2.0 * diverge * diverge * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Moderate dead space (10..30) is risky: only items <= gap can use it.
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits strongly (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit: huge bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere (large residual would be left behind) or stream is early.
    if bin_residual == bin_capacity {
        let waste_if_placed = bin_residual as f64 - item_size as f64;
        // Opening a new bin wastes the mean residual of all open bins.
        score += mean_residual * 0.3;
        // Attractive early when few bins exist.
        score -= (open_bins_count as f64) * 0.2;
        // If placing here would leave a big unusable gap in an open bin,
        // new bin becomes competitive: cancel base advantage.
        if waste_if_placed > 40.0 {
            score -= 15.0;
        }
        if post_residual < 10 {
            score -= 10.0; // fresh bin gives clean large residual
        }
    }

    // Lookahead: if next item fits snugly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_fit = (post_residual - next_item_size) as f64;
        score -= (10.0 - nxt_fit.min(10.0)) * 0.8;
    }
    // If next item would NOT fit here, mild penalty for hoarding space.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 2.0;
    }

    score
}

