pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), non-linearly penalized.
    let mut score = post + 30.0 * norm_post * norm_post;

    // Dead-space penalty grows with stream progress (waste matters more later).
    score += 25.0 * norm_post * norm_post * progress;

    // Reward last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins fit: spread load, keep tight bins for later.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        // Perfect lookahead fit bonus (smooth quadratic).
        score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Prefer bins below mean residual slightly (balance load smoothly).
    score += 5.0 * (post / cap - mean_residual / cap).abs();

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by large
    // chunks are more reusable, so reward "clean" leftover classes.
    let cap = bin_capacity as f64;

    // Class A: post_residual is an exact multiple of 10 -> highly reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual is an exact multiple of 25 -> fits quarter bins.
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Class C: tiny dead space (1..=5) is nearly worthless; penalize mildly
    // unless it was unavoidable (item almost fills bin).
    if post_residual > 0 && post_residual <= 5 {
        score += 3.0;
    }
    // Class D: awkward mid-range leftover (6..=9) — worst dead zone.
    if post_residual >= 6 && post_residual <= 9 {
        score += 5.0;
    }

    // Integer-division threshold: leftover bucket by quarter capacity.
    let quarter = (post_residual * 4) / bin_capacity; // 0..=3
    score -= match quarter {
        0 => 8.0, // nearly full bin — excellent packing
        1 => 4.0, // leaves <= 25% free — decent
        2 => 0.0, // neutral
        _ => 2.0, // leaves > 50% free — wasteful
    };

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 5 {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is bad. Penalize the fresh bin by its full capacity
    // minus a discount when the stream is early (more future items to fill).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += cap * 0.9 - 20.0 * (1.0 - progress);
        // If no open bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= cap * 0.85;
        }
    }

    // Mild preference for bins whose residual deviates from the mean:
    // pack into below-mean-residual (tighter) bins first.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight bias toward using more open bins fully as stream progresses.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical future items.
    // Items are >= 1, but small gaps (< ~20) are rarely reusable.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // "Awkward zone" residuals (20..40) are moderately hard to fill.
    else if post_residual >= 20 && post_residual < 40 {
        score += 12.0 * (1.0 - (post_residual as f64 - 20.0) / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Dead-space avoidance: if the leftover cannot fit the lookahead item,
    // this placement risks stranding space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Conversely, reward leftovers that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // but never prefer a fresh bin over a decent fit in an existing one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base with pressure so it only wins
        // when existing bins score poorly (poor fits / dead space).
        score += 70.0 + pressure;
    } else {
        score += pressure;
    }

    // Slight pull toward bins with residuals near the mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: penalize leaving dead space relative to capacity.
    score += 0.35 * (post_residual as f64 / cap) * (cap - post_residual as f64);

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits perfectly here: strong reward.
            score -= 45.0 * (1.0 - diff / cap);
        } else {
            // Next item cannot follow: penalize proportionally to leftover waste.
            score += 12.0 * (post_residual as f64 / cap);
        }
    } else {
        // Last item: minimize leftover.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in stream: be more willing to open new bins (keep bins tight for future).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, less so later.
        score = cap * (1.0 - 0.5 * progress) - 0.25 * post_residual as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 {
            // Don't open a new bin if this is the only fitting bin and lookahead may fit.
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 0.6 * fill * fill * (bin_capacity as f64);

    // Penalize dead space: post_residual that is too small to be useful.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Early in the stream: encourage opening new bins to build diversity of residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, but less as stream progresses or when bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 18.0 - 12.0 * progress - 0.05 * open_bins_count as f64 - 0.02 * fragmentation;
    } else {
        // Late in the stream: prefer filling existing bins rather than opening new ones.
        score += 8.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean (spread placement).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    let mut score = post_residual as f64;

    // Smooth polynomial coupling: penalize residual quadratically, modulated by progress.
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) - norm_post * norm_item * (1.0 - progress);
    score += 40.0 * poly;

    // Lookahead smooth interaction: reward residual that still fits next item, scaled by progress.
    if next_item_size > 0 {
        let fits_next = (norm_post - norm_next).max(0.0);
        let tight = 1.0 - (norm_post - norm_next).abs();
        score -= 25.0 * fits_next * (0.5 + progress) * tight;
    }

    // Last-chance bonus: smooth reward when few fitting bins, stronger early.
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
    score -= 30.0 * scarcity * (1.0 - 0.5 * progress);

    // Penalize divergence from mean residual smoothly.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * dev * (1.0 + progress);

    // Mild new-bin penalty that grows with progress (prefer consolidating late).
    if bin_residual == bin_capacity {
        score += 15.0 * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic class of leftover

    // Reward residuals that form "perfect" harmonic classes: exactly divisible by
    // common small item sizes (1..=100 range), i.e. post_residual % k == 0.
    let mut divisibility_bonus = 0.0f64;
    for k in [10u32, 20, 25, 50] {
        if post_residual % k == 0 {
            divisibility_bonus += 6.0;
        }
    }
    // Perfectly empty post-residual is ideal.
    if post_residual == 0 {
        divisibility_bonus += 30.0;
    }
    score -= divisibility_bonus;

    // Penalize awkward dead space: residuals in the "unfillable middle band"
    // (too small for most items, i.e. below the minimum plausible item size
    // but not zero). Use integer division thresholds.
    let dead_threshold: u32 = 15;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64 / dead_threshold as f64;
    }

    // Modulo coupling with next item: if next_item_size exactly divides the
    // post_residual, this bin chains perfectly -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }
    // If next item cannot fit here at all, mild penalty if this bin is otherwise good.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post-residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate offset so it wins only
    // when no open bin offers a decent fit. Scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        // If mean residual across open bins is small, opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor), mildly.
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Harmonic class penalty: middle classes (half-full leftovers) are worst.
    score += (class as f64 - 1.0).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0; // gap in [1,9] is nearly worthless
    } else if dead == 0.0 {
        score -= 25.0; // perfect fit strongly rewarded
    }

    // Penalize residual that cannot fit the lookahead item (wasted for k=2 chain).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // keeps room for the next item
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when nothing fits well (large residual waste elsewhere).
    if bin_residual == bin_capacity {
        let poor_alternatives = mean_residual - item_size as f64;
        if poor_alternatives < 0.0 || fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Mild tie-break toward tightest existing fit via mean-residual deviation.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Slight preference for leaving room >= next item
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: bins with residual above average are good targets
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize early opening
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that few typical items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in the stream
        // or when many bins are open (consolidation unlikely).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 45.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_penalty -= 12.0; // big item following: fresh bin useful
        }
        if fit_ratio < 0.6 {
            new_bin_penalty -= 20.0; // existing bins would waste a lot
        }
        score += new_bin_penalty.max(-30.0);
    }

    // Global state coupling: prefer bins deviating favorably from mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill bins with fewer alternatives available.
    score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate
    // residual slightly more since bins are already committed.
    let mut score = pr * (1.0 + 0.6 * progress) + 0.9 * pr * pr / cap;

    // Reward large fill fraction smoothly (cubic in fit_ratio).
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 + 0.5 * progress);

    // Smooth interaction: post_residual penalized more when it cannot
    // plausibly host the lookahead item (smooth logistic-style gate).
    let gap = next_ratio - pr / cap;
    let gate = 1.0 / (1.0 + (-8.0 * gap).exp());
    score += 12.0 * gate * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Scarcity pressure: many open bins -> discourage spreading residual.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: smooth penalty for creating outliers.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: mild smooth penalty so it's chosen only when
    // open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual that can host standard small items is good.
    // Class A: post_residual in {0} handled above; can fit next item exactly or at all.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin remains usable for the lookahead item; reward proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 50.0; // exact lookahead fit
            }
        } else {
            // Dead space relative to lookahead: penalize by unusable gap size.
            score += 0.5 * (post_residual as f64);
        }
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align with
    // typical item granularities, making them more reusable.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Integer-division thresholds: classify post_residual into coarse bands.
    let band = post_residual / 25; // 0..=4
    score += match band {
        0 => -2.0,             // tiny residual: nearly full, good packing
        1 => 0.0,              // 25..49
        2 => 1.0,              // 50..74
        _ => -1.0,             // large residual: fresh-ish bin, fine
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize opening a bin unless current bin
    // would leave an awkward (small, non-harmonic) residual.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Encourage new bin early in stream or when open bins are all crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && progress < 0.9 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 30.0; // item barely fits alone; fresh bin is natural
        }
    }

    // Prefer bins below mean residual (filling crowded bins first keeps spread tight).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for many-fitting-bins situations to close tighter bins.
    if fitting_bins_count > 2 {
        score += 1.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // item (or the lookahead item) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits strongly (near-perfect packing).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // Prefer bins whose residual deviates favorably from the mean
    // (filling the emptiest bins keeps residual distribution balanced).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: neutral baseline with mild penalty so that only
    // genuinely bad fits (large dead space) trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 12.0 + post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear).
    score -= (cap - post) / cap * 25.0;

    // Penalize small dead space that nothing can use later (items >= 1).
    if post > 0.0 && post < 10.0 {
        score += 12.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 30.0;
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a large item early in the stream (reserve space strategy).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score += 55.0;
        score -= 30.0 * progress;
        score -= crowd.min(20.0);
        if item_size as f64 > cap * 0.6 {
            score -= 25.0;
        }
        if mean_residual < item_size as f64 {
            score -= 45.0; // no open bin can realistically hold it
        }
    }

    // Mild preference for filling already-open bins as stream progresses.
    score += progress_weight(step_index, total_items) * post * 0.15;

    // Prefer bins below mean residual (consolidate emptier bins? no: prefer
    // bins with less residual than average to keep big gaps free).
    if bin_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    score
}

#[inline]
fn progress_weight(step_index: usize, total_items: usize) -> f64 {
    1.0 + (step_index as f64 / total_items.max(1) as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let tightness = item_size as f64 / cap;

    // Base: penalize leftover space, with super-linear (quadratic) waste pressure.
    let mut score = pr + 60.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste matters less; late in the stream, minimize leftovers aggressively.
    let progress_coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress);
    score *= progress_coupling;

    // Reward large fills (small post_residual relative to item size) more as stream advances.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * (0.5 + progress);

    // Lookahead: bonus if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - slack * slack);
        } else {
            // Next item cannot use the leftover: penalize dead space smoothly.
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Slight penalty when many bins are open and this one is far from mean residual
    // (encourages balanced bin usage via smooth deviation term).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild crowding pressure: with many open bins, prefer filling existing ones.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: make empty-bin score neutral-high unless residuals are terrible.
    if bin_residual == bin_capacity {
        score = cap + 40.0 * (1.0 - progress) + 10.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals in "useful" classes.
    // Residuals divisible by common small item sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus: f64 = if pr % 50 == 0 { 12.0 }
        else if pr % 25 == 0 { 9.0 }
        else if pr % 20 == 0 { 8.0 }
        else if pr % 10 == 0 { 6.0 }
        else if pr % 5 == 0 { 3.0 }
        else { 0.0 };
        score -= harmonic_bonus;
    }

    // Penalize tiny dead space (< 10, unusable by any item in original range).
    if pr < 10 && pr > 0 {
        score += 15.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual match next item's size or a divisor class?
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            // Next item fits exactly or harmonically into leftover
            if pr == nx {
                score -= 25.0;
            } else if pr % nx == 0 {
                score -= 14.0;
            } else if nx % 10 == 0 && pr % 10 == 0 {
                score -= 7.0;
            }
        } else {
            // Next item cannot use this residual: penalize large leftovers slightly
            score += 0.05 * (pr - (nx - 1).min(pr)) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless current open bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap_f } else { 0.0 };
        // Open a new bin when mean residual is small (bins tight) or early stream with big item
        score += 10.0;
        if fragmentation < 0.25 && open_bins_count > 0 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && open_bins_count > 0 {
            score += 5.0 * progress;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Integer-division threshold on post_residual: quarter classes
    let quarter = post / (bin_capacity / 4).max(1);
    score -= match quarter {
        0 => 5.0,
        1 => 3.0,
        2 => 1.0,
        _ => 0.0,
    };

    // Mild tie-break: prefer bins whose residual is closest to item size in relative terms.
    score += 0.02 * ((bin_residual as f64 - item_size as f64) / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit is gold.
        score -= 100.0;
    }

    // Reward leaving room that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize a gap that is too small for the lookahead item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Pressure from number of open bins: prefer consolidation when many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10 && item_size >= 50);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward when next item fits, scaled by how well it fills the remainder.
            let fill_after_next = post_residual - next_item_size;
            score -= 100.0 - (fill_after_next as f64);
        } else {
            // Penalize leaving a residual the next item cannot use (dead space risk).
            score += 50.0;
        }
    }

    // Compare post-residual to mean residual: avoid making this bin an outlier of wasted space.
    score += 0.5 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Discourage opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a fresh bin.
        score += 60.0;
        // But if the item is large and current open bins have tight residuals, new bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 70.0;
        }
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical item (<= 10 assumed min,
    // but use dynamic estimate from next item size when available).
    let min_useful = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a great chain placement; reward it heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty unless
            // post residual is tiny anyway (near-perfect fill).
            if post_residual > bin_capacity as f64 * 0.25 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residual space is scarce or the item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let global_pressure = mean_residual / bin_capacity as f64;
        // When open bins have plenty of room on average, discourage new bins.
        score += 20.0 * global_pressure;
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
        // Huge items with few fitting bins justify a fresh bin.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 18.0;
        }
    }

    // Mild penalty for leaving large post residual when many bins are open
    // (fragmentation risk grows with open_bins_count).
    let frag = (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * frag;

    // Slight preference for bins whose residual is below the mean (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let progress2 = progress * progress;

    // Base: prefer tight fits (small post_residual), with a smooth
    // non-linear polynomial coupling to stream progress.
    let mut score = post * (1.0 + 0.6 * progress2) - 0.9 * progress * (cap - post) / cap;

    // Smooth dead-space penalty: small-but-nonzero residuals are wasteful.
    // Model unusable space as (post/cap)^2 scaled by how "late" we are,
    // since fragmentation hurts more as the stream matures.
    let frag = (post / cap) * (post / cap);
    score += 25.0 * frag * (0.4 + 0.6 * progress);

    // Lookahead: if the next item fits into the post residual, reward;
    // smooth quadratic kernel over the gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap) * (gap / cap));
        } else {
            score += 4.0 * ((-gap / cap) * (-gap / cap));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: empty bin gets a mild exploration cost,
    // but it vanishes (smoothly) when the fit would be very tight elsewhere
    // is impossible — i.e., when post residual of a fresh bin is small.
    if bin_residual == bin_capacity {
        let new_post = cap - item;
        let tightness = 1.0 - (new_post / cap) * (new_post / cap);
        score += 3.0 + 8.0 * (1.0 - tightness) * (0.5 + 0.5 * progress);
        // If no open bin fits, opening is mandatory: reduce the barrier.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild diversity pressure: many open bins with high mean residual
    // suggests over-fragmentation; favor consolidating into existing bins.
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice"
    // fractions of capacity are more reusable (e.g. 0, 25, 50, 75, 100).
    let pr = post_residual as u32;
    let nice = if pr == 0 { 0.0 }
        else if pr % 25 == 0 { 1.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 3.0 }
        else { 4.0 };
    score -= (4.0 - nice) * 6.0; // reward nicer harmonic classes

    // Perfect fit is the ideal outcome.
    if pr == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: small nonzero residuals are hard to fill later.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Integer-division threshold: residual bucket by quarter capacity.
    let quarter = (pr / (bin_capacity / 4)).min(4);
    score -= (4 - quarter) as f64 * 2.0;

    // Lookahead coupling: does next item fit into post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Exact or near-exact lookahead fit is very valuable.
            let slack = (pr - next_item_size) as f64;
            score -= if slack == 0.0 { 30.0 } else { 12.0 * (1.0 - slack / cap) };
        } else {
            // Next item won't fit here; penalize slightly less if this bin
            // is already tight (harmonic class of next item vs residual).
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity and open bins are already fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let large_item = item_size as f64 / cap;
        score = cap * 0.75
            - large_item * 20.0
            - if fragmentation > cap * 0.5 { 8.0 } else { 0.0 }
            - progress * 5.0;
        // Prefer reusing open bins early; new bins become more acceptable later.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
