            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 178.0 - fill_after_next * 0.85;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 60.0; // avoid tiny dead space after next
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 30.0; // room for two more
            }
            let dsr = fill_after_next / bin_capacity as f64;
            if dsr > 0.18 {
                score += 26.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            if fill_after_next >= 1.0 && fill_after_next <= mean_residual * 0.6 {
                score -= 9.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 52.0 + gap * 0.45;
            if gap > 42.0 {
                score += 24.0;
            }
            if gap <= item_size as f64 {
                score -= 12.0;
            }
        }
    }

    // Relative to mean residual
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance: only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score += 65.0;
        let cap_half = bin_capacity / 2;
        if item_size >= cap_half {
            score -= 95.0; // big items deserve fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 58.0;
        }
        if post_residual > bin_capacity / 3 {
            score -= 44.0;
        }
        if next_item_size > 0 && next_item_size >= cap_half && next_item_size > post_residual {
            score -= 34.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 44.0 * (1.0 - progress);
        score += 0.2 * open_bins_count as f64;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 22.0;
        }
        if item_size < bin_capacity / 5 {
            score += 30.0; // don't waste bins on tiny items
        }
