    // Penalize tiny unusable dead space
    if post_residual > 0 && post_residual < 15 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 32.0;
    }
    if post_residual > 0 && post_residual <= 6 {
        score += 55.0;
    }

    // Endgame tightening
    if total_items > 0 && step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual gap is "dead" if it is small enough that typical items
    // (min size assumed ~10, but adapt via observed stream) cannot use it.
    // Penalize gaps in the unusable band heavily; reward exact/near-exact fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let min_item_guess = 10.0f64.min(bin_capacity as f64 * 0.1);

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if (post_residual as f64) < min_item_guess {
        // Unusable dead space: heavy penalty, escalating with progress
        // (early stream dead space may still be usable later is false —
        // items never grow, so penalize consistently but slightly softer early).
        score += 200.0 + 300.0 * progress;
    } else if (post_residual as f64) < 2.0 * min_item_guess {
        // Marginal zone: gap likely usable only by smallest items.
        score += 40.0 * progress;
    }

    // Penalize wasting a large residual on a small item (poor space utilization).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 150.0 * fill_ratio;

    // --- Open-bins pressure ---
    // Discourage opening new bins when many are already open; encourage
    // consolidation into existing bins.
    let new_bin_candidate = bin_residual == bin_capacity && bin_capacity > 0;
    if new_bin_candidate {
        score += 60.0 + 12.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less desirable.
        score += 80.0 * progress;
        // If the current bin is the only one that fits, never open a new bin.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it rather than strand it.
        score -= 120.0;
    }

    // Slight preference for bins whose residual is close to the item
    // (tight packing), coupling with mean residual as tiebreaker.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow into this bin; mild penalty for
        // leaving a gap that blocks the lookahead item.
        score += 10.0;
    }

    // Mild tiebreak toward bins below mean residual (use emptier bins first
    // keeps tighter bins available for future large items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

