pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic in normalized post residual
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling: prefer tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 3.0 * progress * progress) * 10.0;

    // Penalize post residual that is small but unusable (dead space) — smooth via logistic-like term
    let dead = (1.0 - norm_pr) * (norm_pr / (norm_pr + 0.05));
    score += dead * 8.0;

    // Lookahead: reward if next item fits the post residual (smooth compatibility)
    if next_item_size > 0 {
        let compat = (norm_pr - norm_next).max(0.0) * (1.0 - (norm_pr - norm_next).max(0.0));
        score -= compat * 12.0 * (1.0 + progress);
        // Penalize if next item barely misses this bin's post residual
        let miss = (norm_next - norm_pr).max(0.0);
        score += miss * miss * 6.0;
    }

    // Last-chance bin bonus (smoothly weighted by scarcity of fitting bins)
    if fitting_bins_count <= 1 {
        score -= 5.0 + 10.0 * (1.0 - progress);
    } else {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Slight preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: penalize opening a new bin unless residual is tiny
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) - 10.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity-fraction buckets. Leftovers in "dead" classes are penalized.
    let q = post_residual * 4 / bin_capacity; // 0,1,2,3 class of leftover
    let dead_penalty = match q {
        0 => 0.0,                       // near-perfect fill
        1 => 6.0,                       // small unusable strip
        2 => 3.0,                       // half-ish leftover, still useful
        _ => -2.0,                      // large leftover, flexible
    };
    score += dead_penalty;

    // Exact-fill reward: harmonic ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong bonus, scaled by how snug the fit is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.08 * snug;
        } else {
            // Next item won't fit here: penalize proportional to waste risk.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it wins only if all
        // placements here would leave terrible leftovers.
        score = bin_capacity as f64 * 0.75 + 10.0;
        if post_residual == bin_capacity {
            // it IS the new bin call; make it competitive for bad fits
            score = bin_capacity as f64 - item_size as f64 + 15.0;
        }
    }

    // Late in the stream, prefer tightening fills (fewer bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (balance load).
    score += 0.02 * (mean_residual - bin_residual as f64);

    score
}

