pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post residual is disproportionately good).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose leftover matches next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain: this bin fits both items exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 35.0 - slack * 2.0;
            } else {
                score -= 10.0 / slack.sqrt();
            }
        } else {
            // Next item cannot follow into this bin: penalize proportional to waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap.min(40.0) * 0.4;
        }
    } else {
        // Last item: just prefer tightest fit (already post_residual-driven).
        score -= 5.0;
    }

    // Compare against mean residual: bins already tighter than average are worth filling.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(50.0) * 0.3;
    } else {
        score += (res - mean_residual).min(50.0) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More open bins => more willing to open another (spread load).
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If the best alternative would leave large dead space, new bin looks better:
        // approximate via current mean residual being large.
        score -= (mean_residual - 50.0).max(0.0) * 0.5;
        // Early in stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
