    // late in stream, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * (post_residual == 0) as i32 as f64;

    // Crowding: with many open bins, prefer filling existing ones over spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already fragmented; prefer placing here to balance residuals.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
