pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10-unit classes
    let class = post_residual / 10;
    // Reward placements that land post_residual in "harmonic" residue classes
    // that are highly reusable (multiples of 10 and 25 are common complements).
    let harmonic_bonus: f64 = match class {
        0 => 20.0,          // perfect fit
        1 => 12.0,          // residual 10..19
        2 => 6.0,
        3 => 4.0,
        4 => 6.0,           // residual 40..49 pairs with ~50-60 items
        5 => 10.0,          // residual 50..59 very reusable
        6 => 8.0,
        7 => 3.0,
        8 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold: exact modulo fit is golden
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Dead space penalty: tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling already-open bins when many are open; new bin is a fallback
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: its post_residual equals capacity - item_size.
        // Only attractive if no good existing option (mean residual small)
        // or item is large. Penalize moderately, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 10.0 * progress;
        if item_size >= 50 {
            score -= 5.0; // large items fine in fresh bins
        }
    } else {
        // Existing bin: reward tightness relative to mean residual
        let tightness = mean_residual - post_residual as f64;
        score -= tightness.max(-20.0).min(20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; anything below next_item_size is likely unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 45.0; // tiny dead gap, effectively unusable
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0; // gap unusable by the lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
