    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 10 {
        score -= 8.0; // near-perfect follow-up fit
    }

    // Open-bins pressure: discourage proliferation of bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are few or the fit here is bad.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if open_bins_count > 0 && !bad_fit {
