        score += 30.0;
        if item_size >= 60 {
            score -= 20.0; // large items: fresh bin is reasonable
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // room for the next item in the fresh bin
        }
    }

    // Mild penalty for very tight fits creating unusable slivers < 10.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

