    }

    // Waste ratio penalty for lopsided bins
    let used = bin_capacity - bin_residual;
    if used > 0 {
        let waste_ratio = bin_residual as f64 / used as f64;
        if waste_ratio > 1.0 {
            score += 7.0 * (waste_ratio - 1.0).min(3.0);
