}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post-residual, with non-linear polynomial shaping.
    let x = post / cap; // normalized post residual in [0, 1]
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (reward small post_residual);
    // later, keep residual flexibility (penalize tiny residuals less).
    let poly = 1.0 + 3.0 * progress - 4.0 * progress * progress;
    score += poly * (x * x * cap);

    // Dead-space penalty: non-linearly penalize residuals that cannot fit
    // the next item (smooth via ratio, not a hard threshold).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 20.0 * gap * gap * cap;
    } else if next_item_size > 0 {
        // Reward leaving exactly usable space for the next item.
        let usable = 1.0 - ((next_item_size as f64 - post).abs() / cap);
        score -= 5.0 * usable * usable;
    }

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open (consolidation pressure),
    // coupled smoothly with mean residual divergence.
    let diverge = (mean_residual - post).abs() / cap;
    score += 2.0 * diverge * diverge * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // accommodate the smallest plausible item. Use integer division classes.
    let c = bin_capacity as f64;

    // Class penalty: post_residual in low classes (tiny slivers) are dead space.
    let class = (post_residual / 10) as f64; // 0..10 harmonic class
    score += (10.0 - class) * 0.5; // small residuals penalized extra

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (chain fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: leftover is likely dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer tightening existing bins over spreading
    if open_bins_count > 3 {
        let tight = 1.0 - (post_residual as f64 / c);
        score -= 10.0 * tight;
    }

    // Prefer bins with residual already below mean (compact bins)
    let dev = (bin_residual as f64 - mean_residual) / c;
    score += 5.0 * dev;

    // Early in stream: be pickier about opening new bins (favor reuse)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when item is large
    // relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / c;
        score = 15.0 + 30.0 * large; // base penalty so reuse wins unless justified
        if next_item_size > 0 && next_item_size >= bin_residual - item_size {
            // next item can't join this item in a fresh bin pairing well
            score += 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    score
}

