pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: penalize wasted residual, non-linearly (quadratic dead-space cost).
    let mut score = post * post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); later, tolerate larger residuals
    // since consolidation matters less than bin count.
    let prog_weight = 0.5 + 0.5 * progress * progress;
    score += prog_weight * post;

    // Cubic interaction: mid-stream, strongly reward near-perfect fills.
    let fill = 1.0 - post / cap;
    let mid = 4.0 * progress * (1.0 - progress); // peaks at 1 mid-stream, 0 at ends
    score -= mid * fill * fill * fill * cap * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 2.0;
    }

    // Penalty if this placement strands space relative to other open bins.
    score += (post - mean_residual).abs() * 0.3;

    // Lookahead: reward leaving room for the next item; smooth polynomial.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // Perfect chain fit rewarded; decays smoothly with excess gap.
            let fit_quality = 1.0 - (gap / cap).powi(2);
            score -= fit_quality * nxt * 0.6;
        } else {
            score += (-gap) * 0.5;
        }
    }

    // Slight preference to keep fewer open bins early (compactness).
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tiered reward for tight fits (strengthened)
    if post_residual == 0 {
        score -= 1400.0;
    } else if post_residual <= 3 {
        score -= 360.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    } else if post_residual <= 22 {
        score -= 30.0;
    } else if post_residual <= 38 {
        score -= 10.0;
    }

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 820.0;
        } else if next_item_size <= post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 170.0 - fill_after_next * 0.8;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 55.0;
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 30.0;
            }
            if fill_after_next == 0.0 {
                score -= 45.0;
            }
            if fill_after_next >= next_item_size as f64 && fill_after_next <= bin_capacity as f64 / 4.0 {
                score -= 45.0;
            }
            let dsr = fill_after_next / bin_capacity as f64;
            if dsr > 0.18 {
                score += 24.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            if fill_after_next as f64 > mean_residual * 1.5 {
                score += 14.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 + gap * 0.45;
            if gap > 0.6 * next_item_size as f64 {
                score += 18.0;
            }
            if gap <= item_size as f64 {
                score -= 12.0;
            }
        }
    }

    // Above-average residual bins are good targets
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Only fitting bin: strong preference
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    if fitting_bins_count == 0 {
        score -= 25.0;
    }

    // Tiny dead space penalty
    if post_residual > 0 && post_residual < 15 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 32.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score += 62.0;
        let cap_half = bin_capacity / 2;
        if item_size >= cap_half {
            score -= 90.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 65.0;
        }
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if post_residual > bin_capacity / 3 {
            score -= 42.0;
        }
        if next_item_size > 0 && next_item_size >= cap_half && next_item_size > post_residual {
            score -= 32.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 42.0 * (1.0 - progress);
        score += 0.18 * open_bins_count as f64;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 22.0;
        }
        if post_residual <= 6 && post_residual > 0 {
            score += 50.0;
        }
    }

    // Exact item-refill bonus
    if item_size == post_residual {
        score -= 18.0;
    }

    // Two-item chain lookahead: residual that fits next item twice
    if next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        if after == 0 {
            score -= 110.0;
        } else if after >= next_item_size && after <= bin_capacity / 4 {
            score -= 45.0;
        }
    }

    // Waste ratio penalty for lopsided bins
    let used = bin_capacity - bin_residual;
    if used > 0 {
        let waste_ratio = bin_residual as f64 / used as f64;
        if waste_ratio > 1.0 {
            score += 7.0 * (waste_ratio - 1.0).min(3.0);
        }
    }

    // Endgame squeeze
    if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }
    if total_items > 0 && step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 22.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse if it falls into
    // "unusable" residue classes (small slivers that few items can fill).
    let pr = post_residual;
    if pr > 0 {
        // Small slivers (< 10 in classic regime, scaled) are dead space.
        if pr < 10 {
            score += 60.0;
        }
        // Harmonic bucketing via integer division on capacity quarters.
        let quarter = bin_capacity / 4;
        let bucket = pr / quarter;
        score += match bucket {
            0 => 25.0,          // tiny residue: likely dead
            1 => -15.0,         // mid-small: many items fit
            2 => -5.0,          // mid-large: fine
            _ => 0.0,
        };
        // Modulo coupling: residues that align with common item sizes
        // (multiples of 10) are more fillable.
        if pr % 10 == 0 {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fill.
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits: reward proportional to how well it fills.
        score -= 20.0 * (next_item_size as f64 / pr.max(1) as f64);
    } else if next_item_size > pr && pr > 0 {
        // Next item won't fit here: mild penalty for leaving awkward gap.
        score += 10.0;
    }

    // Stream progression: early on, be willing to open new bins (spread items);
    // later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize relative to good fits, but allow early.
        score += 90.0 - 40.0 * progress;
        // If no open bin fits well, opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins with residual close to mean (balance) mildly.
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;
        // Late stream: reward compacting into already-open bins.
        score -= 15.0 * progress;
    }

    // Many open bins: discourage spreading; favor consolidation.
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

