pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Moderate dead space (10..30) is risky: only items <= gap can use it.
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits strongly (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit: huge bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere (large residual would be left behind) or stream is early.
    if bin_residual == bin_capacity {
        let waste_if_placed = bin_residual as f64 - item_size as f64;
        // Opening a new bin wastes the mean residual of all open bins.
        score += mean_residual * 0.3;
        // Attractive early when few bins exist.
        score -= (open_bins_count as f64) * 0.2;
        // If placing here would leave a big unusable gap in an open bin,
        // new bin becomes competitive: cancel base advantage.
        if waste_if_placed > 40.0 {
            score -= 15.0;
        }
        if post_residual < 10 {
            score -= 10.0; // fresh bin gives clean large residual
        }
    }

    // Lookahead: if next item fits snugly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_fit = (post_residual - next_item_size) as f64;
        score -= (10.0 - nxt_fit.min(10.0)) * 0.8;
    }
    // If next item would NOT fit here, mild penalty for hoarding space.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 2.0;
    }

    score
}

