pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the resulting residual: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }

    // Dead space: residual too small for next item (or any plausible item >= 1).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Compare post_residual against mean residual: prefer bins that keep
    // residuals balanced / close to mean, penalize outliers.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
