pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest item (size 1).
    if post_residual == 0 {
        score -= 25.0; // perfect fit bonus
    } else if post_residual < 10 {
        score -= 8.0; // near-perfect fit
    }

    // Exact-fill detection: item consumes the whole bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            score += 5.0; // bin becomes dead after this placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // the item is large relative to capacity or fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins more when many open bins exist and mean residual is large.
        let waste_penalty = open_bins_count as f64 * 2.0
            + (mean_residual / bin_capacity as f64) * 20.0
            + (1.0 - progress) * 10.0;
        score += 55.0 + waste_penalty - item_ratio * 40.0;
    }

    // Mild preference to fill bins with larger residuals early (balance load).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    // Penalize leaving residuals that only tiny items could use (fragmentation).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tiered rewards for tight post-fit residuals
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    } else if post_residual <= 22 {
        score -= 25.0;
    } else if post_residual <= 38 {
        score -= 8.0;
    }

    // Lookahead: exact match for next item is excellent
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 120.0 - fill_after_next * 0.6;
            // Penalize leaving a sliver that fits nothing
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 45.0;
            }
            // Reward if leftover can hold next item again (repeatability)
            if fill_after_next >= next_item_size as f64 && fill_after_next <= bin_capacity as f64 / 4.0 {
                score -= 35.0;
            }
            if fill_after_next as f64 > mean_residual * 1.5 {
                score += 12.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 + gap * 0.4;
            if gap > 0.6 * next_item_size as f64 {
                score += 15.0;
            }
            if gap <= item_size as f64 {
                score -= 10.0;
            }
        }
    }

    // Relative to mean residual: bins with residual above average are good targets
    score -= 0.4 * (bin_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize tiny dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 30.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0;
        // Big items deserve fresh bins
        if item_size >= bin_capacity / 2 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if post_residual >= bin_capacity / 3 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && next_item_size > post_residual {
            score -= 30.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 60.0;
        }
        score += 40.0 * (1.0 - progress);
        score += 0.2 * open_bins_count as f64;
    }

    // Late-stream compaction: prefer tight fits when near the end
    if step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 20 {
        score -= 18.0;
    }
    if step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 25.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, mildly compressed non-linearly
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Progress coupling: later in the stream, waste matters more (superlinear in progress)
    score += 30.0 * norm_post * norm_post * progress;

    // Perfect fit reward (smooth, non-piecewise)
    score -= 25.0 * (1.0 - norm_post).powi(4) * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize relative to tight fits, relax late in stream
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score = 60.0 + 40.0 * (1.0 - progress) - 30.0 * tightness;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 20.0 * (1.0 - gap / cap).powi(3);
        } else {
            score += 10.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.5 * open_bins_count as f64 * norm_post * (1.0 - progress);

    score
}

