pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect / near-perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-class reward: leftover divisible into nice chunk sizes (10,20,25,50)
    // is more likely reusable by future items.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 30.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 20.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the leftover exactly host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // leftover can still host next item: mild reward scaled by slack
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // leftover smaller than next item: penalize by how wasted it is
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Integer-division threshold classes on post_residual (harmonic bands).
    let band = post_residual / 10; // 0..=10
    score += match band {
        0 => -20.0,
        1 => 5.0,
        2 => 0.0,
        3 => -5.0,
        4 => -8.0,
        5 => -15.0, // half-full leftover is valuable
        _ => (band as f64) * 1.5, // large leftover: prefer filling more
    };

    // Fraction-based refinement: penalize awkward fractions like 0.1-0.2 residual.
    if frac > 0.0 && frac < 0.2 {
        score += 25.0;
    } else if frac >= 0.4 && frac <= 0.6 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when open bins are fragmented
    // or the fit is bad; otherwise discourage spreading.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs();
        score += 35.0
            - fragmentation * 0.4
            - (open_bins_count as f64) * 2.0
            - progress * 10.0;
        if item_size > 60 {
            score -= 20.0; // big items fit great in fresh bin
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - pr) * 0.1; // equals item_size * 0.1, constant offset per item

    // Progress-aware urgency: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

