    // (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Last-chance bin (only one fitting bin): strongly favor using it to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones and
    // discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when mean residual of open bins is
    // low (they are nearly full) or the next item needs fresh space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual < 15.0 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is fine since old ones fill up.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in this bin's post-residual,
    // reward keeping this residual shape.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score += 15.0;
        }
    }

    // Mild preference for bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

