    let gap = mean_residual - bin_residual as f64;
    score += 0.08 * gap;

    // Time horizon: early in the stream, be conservative (favor new bins
    // to preserve flexibility); late, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
