    let mut score = post;

    // Non-linear polynomial shaping of post residual (parent base).
    let x = post / cap;
    let poly = 1.0 + 3.0 * progress - 4.0 * progress * progress;
    score += poly * (x * x * cap);

    // Discrete tight-fit tiers: strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 1400.0;
    } else if post_residual <= 3 {
        score -= 365.0;
    } else if post_residual <= 10 {
        score -= 98.0;
    } else if post_residual <= 22 {
        score -= 30.0;
    } else if post_residual <= 38 {
        score -= 10.0;
    }

    // Next-item lookahead: exact fit is gold; usable remainder is good.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 840.0;
        } else if next_item_size < post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 178.0 - fill_after_next * 0.85;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 60.0;
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 30.0;
            }
            if fill_after_next == 0.0 {
                score -= 42.0;
            }
            if fill_after_next >= next_item_size as f64 && fill_after_next > 0.0 {
                score -= 20.0;
            }
            if fill_after_next >= 1.0 && fill_after_next <= mean_residual * 0.6 {
                score -= 9.0;
            }
            let dsr = fill_after_next / cap;
            if dsr > 0.18 {
                score += 26.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            // Two-of-same-item lookahead: remainder fits another copy.
            if fill_after_next >= next_item_size as f64 && fill_after_next <= cap / 4.0 {
                score -= 50.0;
            }
