            let gap = (next_item_size - post_residual) as f64;
            score += 52.0 + gap * 0.45;
            if gap > 42.0 {
                score += 24.0;
            }
            if gap > 0.6 * next_item_size as f64 {
                score += 18.0;
            }
            if gap <= item_size as f64 {
                score -= 12.0;
            }
        }
    }

    // Dead-space penalty when the next item cannot fit.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 20.0 * gap * gap * cap;
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
        if post_residual >= item_size as f64 * 1.6 {
            score -= 18.0;
        }
    }

    // Consolidation pressure via mean-residual divergence.
    let diverge = (mean_residual - post).abs() / cap;
    score += 2.0 * diverge * diverge * (open_bins_count as f64).sqrt();
