        if fitting_bins_count == 0 {
            score -= 58.0;
        }
        if post_residual > cap / 3.0 {
            score -= 44.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && next_item_size > post_residual {
            score -= 34.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && bin_residual >= next_item_size {
            score -= 20.0;
