        }
        if item_size >= bin_capacity - 8 {
            score -= 70.0;
        }
    }

    // Small residual that is still useful: mild penalty (keep flexibility),
    // but tiny dead residuals late in the stream get a bonus.
    if post_residual > 0 && post_residual < 15 && (next_item_size == 0 || post_residual < next_item_size as f64) {
        score += 32.0;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }
    if progress > 0.9 {
        if post_residual > 0 && post_residual <= item_size as f64 + 4.0 {
            score -= 22.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear emphasis that grows over the stream.
    let mut score = pr * (1.0 + 0.6 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (low post residual relative to item) more strongly late in stream.
    score -= 30.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && pr < next_item_size as f64 {
        score += 12.0 * (1.0 - pr / next_item_size.max(1) as f64) * (0.3 + progress);
    } else if next_item_size > 0 {
        score -= 6.0 * norm_next * norm_pr;
