pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of common item granularities) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        // Check divisibility by common size granules (5, 10, 20, 25, 50)
        if pr % 5 == 0 { harmony -= 4.0; }
        if pr % 10 == 0 { harmony -= 4.0; }
        if pr % 20 == 0 { harmony -= 3.0; }
        if pr % 25 == 0 { harmony -= 2.0; }
        if pr % 50 == 0 { harmony -= 2.0; }
        // Integer-division threshold: leftover >= 10 can still hold a min item
        if pr / 10 >= 1 { harmony -= 2.0; }
        if pr / 10 >= 5 { harmony -= 2.0; }
        score += harmony;

        // Dead-space penalty: leftover too small for any item (1..100 range
        // means leftover < smallest plausible next need is wasted)
        if pr < 10 {
            score += 25.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the post_residual's class match next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here exactly or with harmonic leftover
            let gap = pr - next_item_size;
            score -= 6.0;
            if gap % 10 == 0 { score -= 4.0; }
            if gap == 0 { score -= 10.0; }
        } else {
            // Next item cannot fit here: penalize proportionally to how
            // "stranded" the leftover is relative to next_item_size
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should be penalized unless
    // current item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: large, so it only wins when open bins are bad
        score = (bin_capacity as f64) * 0.9;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 40.0; // large item with no alternative: new bin is fine
        }
        if item_size >= 80 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already low on residual (tight packing)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 8.0;

