            score += 25.0;
        }
        if post_residual <= 6 && post_residual > 0 {
            score += 55.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 70.0;
        }
        if fitting_bins_count == 1 && post_residual >= item_size as f64 * 1.6 {
            score -= 18.0;
        }
        // Prefer new bin when the current best-fit residual is small relative to next item.
        if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.35 && post_residual < next_item_size as f64 {
            score -= 12.0;
        }
    }

    // Small residual that is still useful: mild penalty (keep flexibility).
    if post_residual > 0 && post_residual < 15 && (next_item_size == 0 || post_residual < next_item_size as f64) {
        score += 32.0;
    }
    if progress > 0.75 && post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }
    if progress > 0.9 {
        if post_residual > 0 && post_residual <= item_size as f64 + 4.0 {
            score -= 22.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
