}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-not-zero post residual (dead space), smoothly.
    score += 12.0 * norm_pr * (1.0 - norm_pr).powi(2) * cap;

    // Reward tight fits more strongly as stream progresses.
    score -= 15.0 * progress * (1.0 - norm_pr);

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = (next_item_size as f64 / cap) * (1.0 - norm_pr);
        score -= 10.0 * fit_quality * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Penalize bins far from mean residual (outliers), smooth coupling.
    score += 0.5 * (mean_residual - pr).abs() * (1.0 - progress);

    // New-bin candidate: neutral baseline slightly above good fits, decreasing with progress.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.4 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
