pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual;

    // --- Harmonic class of post_residual: which capacity-fraction class does the dead space fall into? ---
    // k = how many copies of the dead space fit in a full bin (integer division threshold).
    let k = if pr == 0 { 0 } else { (bin_capacity / pr.max(1)).min(20) };
    match k {
        0 => score -= 1000.0,                 // perfect fit: bin closed
        _ if pr <= 5 => score -= 400.0,       // near-perfect, dead space is negligible
        _ if pr <= 15 => score -= 120.0,      // small dead space, still risky but cheap
        _ if pr >= 50 => score -= 20.0,       // large residual stays reusable
        _ => score += 15.0,                   // mid-range dead space (16..49): classic "unusable" zone
    }

    // Modulo-style penalty: dead space that is NOT a divisor-like fraction of capacity is worse.
    if pr > 0 && bin_capacity % pr != 0 {
        score += 5.0;
    }

    // --- Lookahead (k=2): reward bins whose post_residual can host the next item ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 40.0 + 0.4 * slack as f64;
            // harmonic class of the follow-up fit: exact or near-exact chain is gold
            if slack == 0 { score -= 150.0; }
            else if slack <= 5 { score -= 60.0; }
        } else {
            // next item cannot follow here: penalize proportionally to the gap
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // --- New-bin candidate control: only open a new bin when existing fits are poor ---
    if is_new_bin {
        score += 55.0 + 1.5 * open_bins_count as f64;
        // opening a bin early in the stream is cheaper (plenty of future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // last-chance bonus: if this is the only bin that fits, strongly prefer using it
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        // reward bins that are tighter than the fleet average (good consolidation)
        if (pr as f64) < mean_residual {
            score -= 0.3 * (mean_residual - pr as f64);
        }
    }

    // Mild preference for fuller bins among equals (waste-averse tie-break)
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

