        score -= 8.0;
    } else {
        score += 4.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
