            score += 52.0 + gap * 0.45;
            if gap > 42.0 {
                score += 24.0;
            }
            if gap > 0.6 * next_item_size as f64 {
                score += 18.0;
            }
            if gap <= item_size as f64 {
                score -= 12.0;
            }
        }
    }

