        score += 0.15 * open_bins_count as f64;
        // If mean residual is large, prefer using existing bins.
        score += 0.3 * mean_residual;
        // If no other bin fits (fitting_bins_count counts only this new bin), it's forced.
        if fitting_bins_count == 1 {
