    // Mild global pressure: prefer filling existing bins when mean residual is low.
    if bin_residual < bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Prefer bins whose residual is close to item size in absolute terms.
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

