        score -= 8.0;
    }
    // Integer-division class: post_residual in [20, 50] is a "sweet zone"
    let post_class = post_residual / 20;
    score -= match post_class {
        1 => 10.0, // 20..39: most reusable band
        2 => 6.0,  // 40..59
        0 => 0.0,  // 0..19: poor
        _ => 2.0,
    };

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // penalize leaving a sliver after the hypothetical next placement
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 6.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

