    score += (x * x) * (10.0 * progress + 2.0);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (6.0 * progress + 2.0);

    // Last-chance bin: strong reward, decaying smoothly with progress
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post residual (smooth margin term)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln() * (1.0 + progress);

    // Deviation from mean residual: prefer bins near the mean (balance residuals)
    score += ((post - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: prefer opening a fresh bin only when fits are scarce
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 8.0 * progress - (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
