pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of small divisors) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr < 10 {
        15.0 // dead space: unusable for min item size 10
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post residual relative to next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can chain into this bin: reward, scaled by tightness.
            let tight = (pr - next_item_size) as f64;
            score -= 8.0 + 0.1 * (pr as f64 - tight);
        } else {
            // Next item cannot fit: penalize proportional to overshoot class.
            let overshoot = (next_item_size - pr) as f64;
            score += 3.0 + 0.05 * overshoot;
        }
        // Modulo coupling: if next_item_size and pr share harmonic alignment.
        if next_item_size <= pr && (pr % next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor filling it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins create dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead_space_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 10.0 - 0.2 * dead_space_pressure - 5.0 * (1.0 - progress);
        if pr < 10 {
            score += 20.0; // opening fresh bin yields immediate dead space
        }
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild diversity pressure: many open bins -> prefer consolidation.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1400.0;
    } else if post_residual <= 3 {
        score -= 365.0;
    } else if post_residual <= 10 {
        score -= 98.0;
    } else if post_residual <= 22 {
        score -= 30.0;
    } else if post_residual <= 38 {
        score -= 10.0;
    }

    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 840.0;
        } else if next_item_size <= post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 178.0 - fill_after_next * 0.85;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 60.0;
            }
            if fill_after_next == 0.0 {
                score -= 42.0;
            }
            let dsr = fill_after_next / bin_capacity as f64;
            if dsr > 0.18 {
                score += 26.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 30.0;
            }
            if fill_after_next > mean_residual * 1.5 {
                score += 14.0;
            }
            if fill_after_next >= 1.0 && fill_after_next <= mean_residual * 0.6 {
                score -= 9.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 52.0 + gap * 0.45;
            if gap > 42.0 {
                score += 24.0;
            }
            if gap > 0.6 * next_item_size as f64 {
                score += 18.0;
            }
            if gap <= item_size as f64 {
                score -= 12.0;
            }
        }
    }

    score -= 0.5 * (bin_residual as f64 - mean_residual);

    let cap_half = bin_capacity / 2;
    if bin_residual == bin_capacity {
        score += 65.0;
        if item_size >= cap_half {
            score -= 95.0;
        }
        if fitting_bins_count == 0 {
            score -= 58.0;
        }
        if post_residual > bin_capacity / 3 {
            score -= 44.0;
        }
        if next_item_size > 0 && next_item_size >= cap_half && next_item_size > post_residual {
            score -= 34.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && bin_residual >= next_item_size {
            score -= 20.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 44.0 * (1.0 - progress);
        score += 0.2 * open_bins_count as f64;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 22.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= bin_capacity / 4 {
            score += 25.0;
        }
        if post_residual <= 6 && post_residual > 0 {
            score += 55.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 70.0;
        }
        if fitting_bins_count == 1 && post_residual >= item_size as f64 * 1.6 {
            score -= 18.0;
        }
    }

    if next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        if after >= next_item_size && after <= bin_capacity / 4 {
            score -= 50.0;
        }
        if after == 0 {
            score -= 120.0;
        }
    }

    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size as f64) && post_residual < 15 {
        score += 32.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 20 {
        score -= 15.0;
    }
    if total_items > 0 && step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 22.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 30.0;
        }
    }

    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving gaps that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 4.0 + (mean_residual.max(0.0)) * 0.5;
    } else {
        // Slight preference for bins with smaller residual (tighter packing).
        score += (bin_residual as f64) * 0.05;
    }

    // Mild stream-progression pressure to consolidate late in the stream.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

