pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post-residual), with non-linear penalty
    let mut score = pr_norm * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress: early on tolerate slack,
    // later penalize residual dead space more strongly.
    let p = progress;
    score += pr_norm * (0.5 + 2.0 * p * p) * (1.0 - p * (1.0 - p));

    // Reward filling bins nearly exactly (post_residual near 0) with cubic term
    score -= (1.0 - pr_norm).powi(3) * 2.0;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * p;
    } else if fitting_bins_count > 1 {
        score += 0.25 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 1.2 * (1.0 - slack * slack);
        } else {
            // next item won't fit here: penalize leaving awkward residual
            let gap = (nx - pr) / cap;
            score += 0.8 * gap * (1.0 + p);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    let mr = mean_residual / cap;
    score += 0.6 * (pr_norm - mr) * (pr_norm - mr).abs().sqrt().signum();

