    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it attractive only when it enables a good pairing
    if bin_residual == bin_capacity {
        let pair_good = next_item_size > 0 && (cap - it) >= next_item_size as f64
            && (cap - it - next_item_size as f64) <= 0.15 * cap;
        if pair_good {
            score -= 2.5;
        } else {
            score += 1.5 + 2.0 * p;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify dead space by capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead space classes: tiny dead space is fine, medium is bad, large is recoverable.
    if post <= eighth {
        // Excellent packing: near-perfect fit -> strong reward
        score -= 12.0;
        // Perfect fit bonus (exact zero or exact class boundary)
        if post_residual == 0 { score -= 15.0; }
        else if post_residual % 10 == 0 { score -= 4.0; }
    } else if post <= quarter {
        // Medium dead space: penalize, but less if it forms a "harmonic" slot
        // that a common item class (10..=25) could still fill.
        if post_residual >= 10 && post_residual <= 25 {
            score -= 2.0;
        } else {
            score += 6.0;
        }
    } else {
        // Large residual: generally good (bin stays flexible), reward mildly
        score -= 3.0;
    }

    // --- Modulo class coupling with the lookahead item ---
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits here: big reward, scaled by how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - snug / cap);
            // Harmonic pairing: item + next fills bin to a multiple of 10
            if (item_size + next_item_size) % 10 == 0 {
                score -= 6.0;
            }
            // Exact chain fill: residual consumed exactly by next item
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's residual: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 10.0 * (gap / cap);
            // But if the dead space belongs to a "harmonic class" (multiple of 10/20),
            // future items of that class may still use it: soften penalty.
            if post_residual % 20 == 0 && post_residual >= 20 {
                score -= 4.0;
            }
        }
    } else {
        // Last item: minimize final waste aggressively
        score += post as f64 * 0.5;
        if post_residual == 0 { score -= 20.0; }
    }

    // --- Integer-division threshold on residual class ---
    let residual_class = post_residual / 13; // coarse harmonic bucket
    score += residual_class as f64 * 1.5;     // prefer smaller bucket index (tighter fill)

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }
    // Many alternatives exist: this bin is less critical, slight penalty for waste
    if fitting_bins_count > 3 && post > quarter {
        score += 4.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost. Prefer it only when the item is large
        // relative to typical residuals or existing bins are nearly full.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let item_frac = item_size as f64 / cap;
        let new_bin_cost = 25.0
            - 15.0 * mean_tightness
            + 10.0 * (1.0 - progress)
            - 8.0 * item_frac;
        // If no open bin fits at all, opening is mandatory: reduce cost
        if fitting_bins_count == 0 {
            score = new_bin_cost - 30.0;
        } else {
            score = post + new_bin_cost;
        }
    }

    // --- Stream progression: later in stream, be greedier about tight fits ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post <= eighth {
        score -= 5.0 * progress;
    }

    // --- Open bins pressure: many open bins -> prefer consolidation into fuller bins ---
    if open_bins_count > 8 {
        score += 0.05 * post as f64; // amplify waste penalty when bin count is high
    }

    score
}

