        if next_item_size == post_residual {
            score -= 830.0;
        } else if next_item_size <= post_residual {
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 175.0 - fill_after_next * 0.82;
            if fill_after_next > 0.0 && fill_after_next < 5.0 {
                score += 58.0;
            }
            if fill_after_next == 0.0 {
                score -= 42.0;
            }
            let dsr = fill_after_next / bin_capacity as f64;
            if dsr > 0.18 {
                score += 26.0 * dsr;
            } else if dsr < 0.05 {
                score -= 12.0;
            }
            if fill_after_next >= next_item_size as f64 * 2.0 {
                score -= 30.0;
            }
            if fill_after_next > 0.0 && fill_after_next <= mean_residual * 0.6 {
                score -= 9.0;
            }
            if fill_after_next as f64 > mean_residual * 1.5 {
                score += 14.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 + gap * 0.44;
            if gap > 42.0 {
                score += 23.0;
            }
            if gap > 0.6 * next_item_size as f64 {
                score += 17.0;
            }
            if gap <= item_size as f64 {
                score -= 11.0;
            }
            if gap > bin_capacity as f64 * 0.35 {
                score += 28.0;
            }
        }
    }

    // Above-average residual bins are good targets
    score -= 0.48 * (bin_residual as f64 - mean_residual);

    // Last chance: favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Small unusable dead space penalty
    if post_residual > 0 && post_residual < 10 && next_item_size as f64 > post_residual as f64 {
        score += 32.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        score += 64.0;
        let cap_half = bin_capacity / 2;
        if item_size >= cap_half {
            score -= 92.0;
        }
        if fitting_bins_count == 0 {
            score -= 56.0;
        }
        if post_residual > bin_capacity / 3 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= cap_half && next_item_size > post_residual {
            score -= 32.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 43.0 * (1.0 - progress);
        score += 0.19 * open_bins_count as f64;
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 21.0;
        }
        if item_size >= bin_capacity - 8 {
            score -= 68.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual && post_residual <= bin_capacity / 4 {
            score += 25.0;
        }
        if post_residual <= 6 && post_residual > 0 {
            score += 50.0;
        }
        if fitting_bins_count <= 2 && item_size as f64 > 0.55 * bin_capacity as f64 {
            score -= 24.0;
        }
    }

    // Mild consolidation pressure
    score -= 0.1 * open_bins_count as f64;

    // Residual that can chain-fit the next item twice is valuable
    if next_item_size > 0 && next_item_size < post_residual {
        let after = post_residual - next_item_size;
        if after >= next_item_size && after <= bin_capacity / 4 {
            score -= 50.0;
        }
        if after == 0 {
            score -= 115.0;
        }
    }

    // Late-stream fine tuning
    if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 20 {
        score -= 16.0;
    }
    if total_items > 0 && step_index > total_items * 9 / 10 {
        if post_residual > 0 && post_residual <= item_size + 4 {
            score -= 22.0;
        }
        if bin_residual == bin_capacity && item_size < bin_capacity / 5 {
            score += 30.0;
        }
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 35.0 * (1.0 - tightness);
    }

    score
}
